// spec: .qa/e2e/specs/important-dates.md
// seed: tests/seed.user1.spec.ts
// Шаги пройдены в живом браузере (реальная дата в нём тоже 3.10.2026); page.clock.setFixedTime — по плану, в живом режиме недоступен.
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { daysInMonth, gregMonthName, hebrewDayMonth, hebrewMonthRange, isoDate } from '../_helpers/dates';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

test.describe('Важные даты и אזכרות', () => {
  test('ID-04 Календарь в окне даты — дни текущего месяца, двойной еврейский заголовок, выбор месяца/года, без ручного ввода #6a86f7e0 @prod-safe', async ({ page }) => {
    // 1. `/home` → «הוספת תאריך חשוב» → «אזכרה».
    // Часы НЕ сдвигаются (сдвиг назад ломал сессию — 401): «сегодня» реальное, ожидаемые месяцы/еврейские даты
    // вычисляются (на 3.10.2026 получаются ровно строки кейса: «אוקטובר 2026», «תשרי – חשון תשפ״ז», «כ׳ תשרי»…).
    const today = new Date();
    const Y = today.getFullYear();
    const M = today.getMonth();
    const curTitle = `${gregMonthName(Y, M)} ${Y}`;
    // Предыдущий месяц (в кейсе — «ספטמבר 2026» при текущем октябре).
    const pY = M === 0 ? Y - 1 : Y;
    const pM = M === 0 ? 11 : M - 1;
    const prevTitle = `${gregMonthName(pY, pM)} ${pY}`;
    const iso = (y: number, m0: number, d: number) => isoDate(new Date(y, m0, d, 12));

    await page.goto('/home');
    await page.getByRole('button', { name: 'הוספת תאריך חשוב' }).click();
    await page.getByRole('button', { name: 'אזכרה', exact: true }).click();
    const dialog = page.getByRole('dialog');

    // 2. Прочитать календарь текущего месяца.
    await expect(dialog.getByRole('button', { name: `${curTitle}: בחירת שנה וחודש` })).toBeVisible();
    await expect(dialog.getByText(hebrewMonthRange(Y, M))).toBeVisible();
    const days = dialog.getByRole('radio');
    const curDays = daysInMonth(Y, M);
    await expect(days).toHaveCount(curDays);
    for (let d = 1; d <= curDays; d++) {
      await expect(dialog.getByRole('radio', { name: new RegExp(`^${iso(Y, M, d)}, .+`) })).toHaveCount(1);
    }
    await expect(dialog.getByRole('radio', { name: new RegExp(`^${iso(Y, M, 1)}, ${hebrewDayMonth(new Date(Y, M, 1, 12))}`) })).toBeVisible();

    // 3. «<месяц> <год>: בחירת שנה וחודש» → «השנה הקודמת» / «השנה הבאה» → предыдущий месяц.
    await dialog.getByRole('button', { name: `${curTitle}: בחירת שנה וחודש` }).click();
    await expect(dialog.getByRole('button', { name: `${Y}: בחירת שנה אחרת` })).toBeVisible();
    await expect(dialog.getByRole('button', { name: 'השנה הקודמת' })).toBeVisible();
    await expect(dialog.getByRole('button', { name: 'השנה הבאה' })).toBeVisible();
    for (const m of ['ינואר', 'פברואר', 'מרץ', 'אפריל', 'מאי', 'יוני', 'יולי', 'אוגוסט', 'ספטמבר', 'אוקטובר', 'נובמבר', 'דצמבר']) {
      await expect(dialog.getByRole('button', { name: new RegExp(`^${m} ${Y}`) })).toBeVisible();
    }
    await expect(dialog.getByText('חזרה ללוח')).toBeVisible();
    await dialog.getByRole('button', { name: 'השנה הקודמת' }).click();
    await dialog.getByRole('button', { name: 'השנה הבאה' }).click(); // в прошлом году «השנה הבאה» активна
    if (pY !== Y) await dialog.getByRole('button', { name: 'השנה הקודמת' }).click(); // январь → декабрь прошлого года
    await dialog.getByRole('button', { name: prevTitle }).click();

    await expect(dialog.getByText(prevTitle, { exact: true })).toBeVisible();
    await expect(dialog.getByText(hebrewMonthRange(pY, pM))).toBeVisible();
    const prevDays = daysInMonth(pY, pM);
    await expect(dialog.getByRole('radio')).toHaveCount(prevDays);
    await expect(dialog.getByRole('radio', { name: new RegExp(`^${iso(pY, pM, 1)}, `) })).toBeVisible();
    await expect(dialog.getByRole('radio', { name: new RegExp(`^${iso(pY, pM, prevDays)}, `) })).toBeVisible();

    // Нет «או הקלידו…» и кнопки «מעבר»
    await expect(page.locator('body')).not.toContainText('או הקלידו');
    await expect(dialog.getByText('מעבר', { exact: true })).toHaveCount(0);
    // Нет горизонтальной прокрутки
    expect(await page.evaluate(() => document.documentElement.scrollWidth <= document.documentElement.clientWidth)).toBe(true);

    // 4. Закрыть «סגירה» без сохранения.
    await dialog.getByRole('button', { name: 'סגירה' }).click();
    await expect(page.getByRole('dialog')).toHaveCount(0);
  });
});
